/** Per-frame film grain — warm-tinted, 5% opacity */
export const Grain: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const seed = frame % 120;
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
        <defs>
          <filter id={`g${seed}`} x="0" y="0" width="100%" height="100%">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.82"
              numOctaves="4"
              seed={seed}
              stitchTiles="stitch"
            />
            <feColorMatrix
              type="matrix"
              values="0.38 0.5  0.12 0 0
                      0.28 0.58 0.14 0 0
                      0.22 0.5  0.28 0 0
                      0    0    0    0 0.05"
            />
          </filter>
        </defs>
        <rect width={width} height={height} filter={`url(#g${seed})`} />
      </svg>
    </AbsoluteFill>
  );
};

