// ── Documentary Frame ──────────────────────────────────────────────────────────

/** The frame dimensions within the 1920×1080 canvas */
export const FRAME_W = 1600;
export const FRAME_H = 900;

const FRAME_X = (1920 - FRAME_W) / 2; // 160px dark border each side
const FRAME_Y = (1080 - FRAME_H) / 2; // 90px dark border top/bottom

/**
 * DocumentaryFrame — the consistent outer shell for every composition.
 *
 * Outer surround (1920×1080):
 *   • Dark charcoal base (#1c1c1c)
 *   • Animated neutral film grain at ~2.5% opacity — matches the warm
 *     grain inside the frame and makes the whole piece feel like one
 *     printed/film artefact rather than a screen floating in a void
 *   • Radial vignette (~14% opacity) pulls the eye toward the frame centre
 *
 * Inner frame (1600×900):
 *   • overflow:hidden clips all content animations
 *   • Thin edge glow + deep drop shadow lifts the frame off the surround
 *
 * Watermark: bottom-right inside the frame (matching original position).
 */
export const DocumentaryFrame: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  // Cycle grain seed every 4 frames — slow enough to feel like paper texture,
  // fast enough to read as genuine film grain rather than a static pattern.
  const seed = Math.floor(frame / 4) % 30;

  return (
    <AbsoluteFill style={{ fontFamily, overflow: "hidden" }}>

      {/* ── Dark charcoal base ── */}
      <AbsoluteFill style={{ background: "#1c1c1c" }} />

      {/* ── Animated neutral grain on the outer surround (~2.5% opacity) ── */}
      <AbsoluteFill style={{ pointerEvents: "none" }}>
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", top: 0, left: 0, opacity: 0.025 }}
        >
          <defs>
            <filter
              id={`outer-grain-${seed}`}
              x="0"
              y="0"
              width="100%"
              height="100%"
            >
              <feTurbulence
                type="fractalNoise"
                baseFrequency="0.78"
                numOctaves="4"
                seed={seed}
                stitchTiles="stitch"
              />
              {/* Neutral white-grey tint — deliberately cooler than the warm
                  inner grain so the two areas read as distinct zones */}
              <feColorMatrix
                type="matrix"
                values="0 0 0 0 0.85
                        0 0 0 0 0.85
                        0 0 0 0 0.85
                        0 0 0 0 1"
              />
            </filter>
          </defs>
          <rect
            width={width}
            height={height}
            filter={`url(#outer-grain-${seed})`}
          />
        </svg>
      </AbsoluteFill>

      {/* ── Radial vignette — edges darken ~14%, centre untouched ── */}
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(ellipse 80% 75% at center, transparent 30%, rgba(0,0,0,0.14) 100%)",
          pointerEvents: "none",
        }}
      />

      {/* ── Content window ── */}
      <div
        style={{
          position: "absolute",
          left: FRAME_X,
          top: FRAME_Y,
          width: FRAME_W,
          height: FRAME_H,
          overflow: "hidden",
          // Thin frosted-glass edge glow + deep shadow lifts the frame
          boxShadow:
            "0 0 0 1px rgba(255,255,255,0.08), 0 8px 48px rgba(0,0,0,0.7), 0 40px 120px rgba(0,0,0,0.5)",
        }}
      >
        {children}

        {/* ── Watermark — bottom-right inside the frame (original position) ── */}
        <div
          style={{
            position: "absolute",
            bottom: 50,
            right: 72,
            fontFamily,
            fontSize: 30,
            fontWeight: 800,
            color: "#111",
            opacity: 0.2,
            letterSpacing: -1,
            userSelect: "none",
            pointerEvents: "none",
          }}
        >
          90th
        </div>
      </div>

    </AbsoluteFill>
  );
};
