/**
 * TeamLineup — Tactical formation on a parchment-toned pitch diagram.
 * Players placed via x/y (0–100) grid. Pitch lines in warm tone to stay on-brand.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Overline,
  DisplayTitle,
  MetaLine,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const LineupPlayerSchema = z.object({
  name:     z.string(),
  number:   z.number().optional(),
  x:        z.number(), // 0–100 (percentage across pitch width)
  y:        z.number(), // 0–100 (percentage down pitch height, 0=top/keeper end)
  isCaptain: z.boolean().default(false),
});

export const TeamLineupPropsSchema = z.object({
  teamName:   z.string(),
  formation:  z.string(),           // e.g. "4-3-3"
  badgeSlug:  z.string(),
  teamColor:  z.string(),
  opposition: z.string().optional(),
  date:       z.string().optional(),
  players:    z.array(LineupPlayerSchema),
});

export type LineupPlayer    = z.infer<typeof LineupPlayerSchema>;
export type TeamLineupProps = z.infer<typeof TeamLineupPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const HEADER_START   = 0;
const PITCH_START    = 20;
const PLAYER_START   = 45;
const PLAYER_STAGGER = 5;

// ── Pitch SVG ────────────────────────────────────────────────────────────────
const PitchMarkings: React.FC<{ w: number; h: number; opacity: number }> = ({ w, h, opacity }) => {
  const stroke = "rgba(0,0,0,0.12)";
  const sw     = 2;

  const penSpotTop    = h * 0.12;   // penalty spot from top
  const penSpotBottom = h - h * 0.12;
  const dRadius       = 62;

  return (
    <svg
      width={w}
      height={h}
      style={{ position: "absolute", top: 0, left: 0, opacity }}
    >
      <defs>
        {/* Only show the D arc below the top penalty box */}
        <clipPath id="topDClip">
          <rect x={0} y={h * 0.17} width={w} height={h} />
        </clipPath>
        {/* Only show the D arc above the bottom penalty box */}
        <clipPath id="botDClip">
          <rect x={0} y={0} width={w} height={h - h * 0.17} />
        </clipPath>
      </defs>

      {/* Outline */}
      <rect x={1} y={1} width={w - 2} height={h - 2} stroke={stroke} strokeWidth={sw} fill="none" />
      {/* Centre line */}
      <line x1={0} y1={h / 2} x2={w} y2={h / 2} stroke={stroke} strokeWidth={sw} />
      {/* Centre circle */}
      <circle cx={w / 2} cy={h / 2} r={60} stroke={stroke} strokeWidth={sw} fill="none" />
      <circle cx={w / 2} cy={h / 2} r={4} fill={stroke} />
      {/* Top penalty box */}
      <rect x={w * 0.2} y={0} width={w * 0.6} height={h * 0.17} stroke={stroke} strokeWidth={sw} fill="none" />
      {/* Top goal box */}
      <rect x={w * 0.35} y={0} width={w * 0.3} height={h * 0.07} stroke={stroke} strokeWidth={sw} fill="none" />
      {/* Top penalty spot */}
      <circle cx={w / 2} cy={penSpotTop} r={3} fill={stroke} />
      {/* Top D arc — only portion outside the penalty box */}
      <circle cx={w / 2} cy={penSpotTop} r={dRadius} stroke={stroke} strokeWidth={sw} fill="none" clipPath="url(#topDClip)" />
      {/* Bottom penalty box */}
      <rect x={w * 0.2} y={h - h * 0.17} width={w * 0.6} height={h * 0.17} stroke={stroke} strokeWidth={sw} fill="none" />
      {/* Bottom goal box */}
      <rect x={w * 0.35} y={h - h * 0.07} width={w * 0.3} height={h * 0.07} stroke={stroke} strokeWidth={sw} fill="none" />
      {/* Bottom penalty spot */}
      <circle cx={w / 2} cy={penSpotBottom} r={3} fill={stroke} />
      {/* Bottom D arc — only portion outside the penalty box */}
      <circle cx={w / 2} cy={penSpotBottom} r={dRadius} stroke={stroke} strokeWidth={sw} fill="none" clipPath="url(#botDClip)" />
    </svg>
  );
};

// ── Player dot ───────────────────────────────────────────────────────────────
const PlayerDot: React.FC<{
  player: LineupPlayer;
  index: number;
  frame: number;
  fps: number;
  color: string;
  pitchW: number;
  pitchH: number;
}> = ({ player, index, frame, fps, color, pitchW, pitchH }) => {
  const delay   = PLAYER_START + index * PLAYER_STAGGER;
  const prog    = spring({ frame: frame - delay, fps, config: SPRINGS.bounce });
  const opacity = interpolate(prog, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const scale   = interpolate(prog, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  const cx = (player.x / 100) * pitchW;
  const cy = (player.y / 100) * pitchH;
  const [r, g, b] = hexToRgb(color);

  return (
    <div
      style={{
        position: "absolute",
        left: cx,
        top: cy,
        transform: `translate(-50%, -50%) scale(${scale})`,
        opacity,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 6,
      }}
    >
      {/* Circle */}
      <div
        style={{
          width: 60,
          height: 60,
          borderRadius: "50%",
          backgroundColor: color,
          border: "4px solid rgba(255,255,255,0.9)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: `0 6px 20px rgba(${r},${g},${b},0.45)`,
        }}
      >
        {player.number != null && (
          <span style={{ fontSize: 22, fontWeight: 800, color: "#fff", fontFamily }}>
            {player.number}
          </span>
        )}
      </div>

      {/* Name */}
      <div
        style={{
          fontSize: 20,
          fontWeight: 700,
          color: COLORS.primary,
          fontFamily,
          backgroundColor: "rgba(245,240,232,0.92)",
          borderRadius: 6,
          padding: "4px 10px",
          whiteSpace: "nowrap",
          letterSpacing: 0.2,
          border: `1px solid rgba(0,0,0,0.1)`,
          boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
        }}
      >
        {player.isCaptain ? `${player.name} (C)` : player.name}
      </div>
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const TeamLineup: React.FC<TeamLineupProps> = ({
  teamName,
  formation,
  badgeSlug,
  teamColor,
  opposition,
  date,
  players,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: SPRINGS.header });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const pProg    = spring({ frame: frame - PITCH_START, fps, config: SPRINGS.feature });
  const pOpacity = interpolate(pProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const pScale   = interpolate(pProg, [0, 1], [0.96, 1], { extrapolateRight: "clamp" });

  // Pitch fills 66% of the content area and stays within the 1080 frame height
  const pitchW = 1160;
  const pitchH = 900;

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "stretch",
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        {/* ── Left: info panel — 33% ── */}
        <div
          style={{
            width: "33%",
            flexShrink: 0,
            paddingLeft: 80,
            paddingRight: 40,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            gap: 14,
            opacity: hOpacity,
            transform: `translateY(${hY}px)`,
          }}
        >
          <img
            src={staticFile(`badges/${badgeSlug}`)}
            width={84}
            height={84}
            style={{ objectFit: "contain", marginTop: 60 }}
          />
          <Overline>Starting XI</Overline>
          <DisplayTitle size={48}>{teamName}</DisplayTitle>
          {(opposition || date) && (
            <div style={{ fontSize: 19 }}>
              <MetaLine color={COLORS.primary}>
                {[opposition && `vs ${opposition}`, date].filter(Boolean).join(" · ")}
              </MetaLine>
            </div>
          )}
          <div
            style={{
              marginTop: 8,
              display: "inline-block",
              backgroundColor: teamColor,
              borderRadius: 10,
              padding: "10px 24px",
              boxShadow: `0 0 18px 4px ${rgbaFromHex(teamColor, 0.3)}`,
              alignSelf: "flex-start",
            }}
          >
            <span style={{ fontSize: 22, fontWeight: 800, color: "#fff", fontFamily, letterSpacing: -0.3 }}>
              {formation}
            </span>
          </div>
        </div>

        {/* ── Right: pitch — 67% ── */}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "flex-start",
            justifyContent: "center",
            paddingTop: 0,
            paddingBottom: 0,
            paddingRight: 30,
          }}
        >
          <div
            style={{
              width: pitchW,
              height: pitchH,
              maxWidth: "100%",
              maxHeight: "100%",
              position: "relative",
              opacity: pOpacity,
              transform: `scale(${pScale})`,
              transformOrigin: "center center",
              backgroundColor: "rgba(232,217,165,0.35)",
              borderRadius: 12,
              border: `1px solid rgba(0,0,0,0.08)`,
              boxShadow: "0 20px 60px rgba(0,0,0,0.1)",
              overflow: "hidden",
            }}
          >
            <PitchMarkings w={pitchW} h={pitchH} opacity={pOpacity} />
            {players.map((player, i) => (
              <PlayerDot
                key={i}
                player={player}
                index={i}
                frame={frame}
                fps={fps}
                color={teamColor}
                pitchW={pitchW}
                pitchH={pitchH}
              />
            ))}
          </div>
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
