/**
 * DisciplinaryRecord — Timeline of a player's disciplinary incidents.
 * Each row shows: date, incident description, ban length, club at the time.
 * Severity is colour-coded (yellow = warning, red = ban, black = serious).
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Card,
  Overline,
  DisplayTitle,
  MetaLine,
  hexToRgb,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const IncidentSchema = z.object({
  date:        z.string(),                                   // e.g. "April 2013"
  incident:    z.string(),                                   // e.g. "Biting — Branislav Ivanović"
  ban:         z.string(),                                   // e.g. "10 matches" or "No ban"
  club:        z.string(),
  badgeSlug:   z.string(),
  clubColor:   z.string(),
  severity:    z.enum(["warning", "ban", "serious"]),        // controls colour coding
});

export const DisciplinaryRecordPropsSchema = z.object({
  playerName: z.string(),
  badgeSlug:  z.string(),
  incidents:  z.array(IncidentSchema),
});

export type Incident              = z.infer<typeof IncidentSchema>;
export type DisciplinaryRecordProps = z.infer<typeof DisciplinaryRecordPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const HEADER_START = 0;
const ROW_START    = 25;
const ROW_STAGGER  = 12;

// ── Severity colours ─────────────────────────────────────────────────────────
const SEVERITY: Record<Incident["severity"], { bg: string; pill: string; dot: string }> = {
  warning:  { bg: "rgba(251,188,4,0.12)",  pill: "rgba(251,188,4,0.25)",  dot: "#FBBC04" },
  ban:      { bg: "rgba(220,53,69,0.10)",   pill: "rgba(220,53,69,0.22)",  dot: "#DC3545" },
  serious:  { bg: "rgba(30,30,30,0.12)",    pill: "rgba(30,30,30,0.22)",   dot: "#111111" },
};

// ── Incident row ──────────────────────────────────────────────────────────────
const IncidentRow: React.FC<{
  incident: Incident;
  index: number;
  frame: number;
  fps: number;
}> = ({ incident, index, frame, fps }) => {
  const delay   = ROW_START + index * ROW_STAGGER;
  const prog    = spring({ frame: frame - delay, fps, config: SPRINGS.row });
  const opacity = interpolate(prog, [0, 0.35], [0, 1], { extrapolateRight: "clamp" });
  const transX  = interpolate(prog, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const sev     = SEVERITY[incident.severity];
  const [r, g, b] = hexToRgb(incident.clubColor);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        height: 76,
        backgroundColor: sev.bg,
        borderRadius: 10,
        marginBottom: 6,
        opacity,
        transform: `translateX(${transX}px)`,
        position: "relative",
        paddingLeft: 20,
        paddingRight: 20,
        overflow: "hidden",
      }}
    >
      {/* Severity dot */}
      <div
        style={{
          width: 10,
          height: 10,
          borderRadius: "50%",
          backgroundColor: sev.dot,
          flexShrink: 0,
          marginRight: 16,
          boxShadow: `0 0 8px 3px ${sev.dot}55`,
        }}
      />

      {/* Date */}
      <div
        style={{
          width: 120,
          fontSize: 13,
          fontWeight: 700,
          color: COLORS.muted,
          fontFamily,
          letterSpacing: 0.5,
          flexShrink: 0,
        }}
      >
        {incident.date}
      </div>

      {/* Incident description */}
      <div style={{ flex: 1, paddingLeft: 8, paddingRight: 16 }}>
        <div
          style={{
            fontSize: 17,
            fontWeight: 600,
            color: COLORS.primary,
            fontFamily,
            letterSpacing: -0.2,
          }}
        >
          {incident.incident}
        </div>
        <div
          style={{
            fontSize: 13,
            fontWeight: 400,
            color: COLORS.muted,
            fontFamily,
            marginTop: 2,
          }}
        >
          {incident.club}
        </div>
      </div>

      {/* Club badge */}
      <div
        style={{
          width: 44,
          height: 44,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginRight: 16,
          flexShrink: 0,
        }}
      >
        <img
          src={staticFile(`badges/${incident.badgeSlug}`)}
          width={36}
          height={36}
          style={{ objectFit: "contain" }}
        />
      </div>

      {/* Ban pill */}
      <div
        style={{
          backgroundColor: sev.pill,
          borderRadius: 8,
          padding: "6px 14px",
          flexShrink: 0,
        }}
      >
        <span
          style={{
            fontSize: 14,
            fontWeight: 700,
            color: COLORS.primary,
            fontFamily,
            letterSpacing: 0.2,
          }}
        >
          {incident.ban}
        </span>
      </div>
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const DisciplinaryRecord: React.FC<DisciplinaryRecordProps> = ({
  playerName,
  badgeSlug,
  incidents,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: SPRINGS.header });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const totalBans = incidents.filter(i => i.severity !== "warning").length;

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: 100,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        <div style={{ width: 1440 }}>

          {/* Header */}
          <div
            style={{
              opacity: hOpacity,
              transform: `translateY(${hY}px)`,
              display: "flex",
              alignItems: "center",
              gap: 32,
              marginBottom: 32,
            }}
          >
            <img
              src={staticFile(`badges/${badgeSlug}`)}
              width={72}
              height={72}
              style={{ objectFit: "contain", flexShrink: 0 }}
            />
            <div>
              <Overline>Disciplinary Record</Overline>
              <DisplayTitle size={56}>{playerName}</DisplayTitle>
              <MetaLine>{totalBans} bans · {incidents.length} incidents</MetaLine>
            </div>

            {/* Legend */}
            <div style={{ marginLeft: "auto", display: "flex", gap: 20, paddingRight: 4 }}>
              {(["warning", "ban", "serious"] as const).map(sev => (
                <div key={sev} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <div style={{ width: 10, height: 10, borderRadius: "50%", backgroundColor: SEVERITY[sev].dot }} />
                  <span style={{ fontSize: 12, fontWeight: 600, color: COLORS.muted, fontFamily, textTransform: "uppercase", letterSpacing: 1 }}>
                    {sev}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Incident rows */}
          <Card style={{ padding: "16px 20px" }}>
            {incidents.map((incident, i) => (
              <IncidentRow
                key={i}
                incident={incident}
                index={i}
                frame={frame}
                fps={fps}
              />
            ))}
          </Card>
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
