/**
 * MatchResult — Cinematic score card for a single match.
 * Centre: Home badge | score | Away badge. Score digits count up.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Card,
  Overline,
  MetaLine,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const MatchResultPropsSchema = z.object({
  homeTeam:       z.string(),
  awayTeam:       z.string(),
  homeBadgeSlug:  z.string(),
  awayBadgeSlug:  z.string(),
  homeColor:      z.string(),
  awayColor:      z.string(),
  homeScore:      z.number(),
  awayScore:      z.number(),
  date:           z.string(),          // e.g. "05 February 2014"
  competition:    z.string().default("Premier League"),
  venue:          z.string().optional(),
  scorers:        z.array(z.string()).optional(), // e.g. ["Suárez 14'", "Sturridge 38'"]
});

export type MatchResultProps = z.infer<typeof MatchResultPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const META_START   = 0;
const CARD_START   = 18;
const SCORE_START  = 40;
const SCORER_START = 80;

// ── Main composition ───────────────────────────────────────────────────────────
export const MatchResult: React.FC<MatchResultProps> = ({
  homeTeam,
  awayTeam,
  homeBadgeSlug,
  awayBadgeSlug,
  homeColor,
  awayColor,
  homeScore,
  awayScore,
  date,
  competition,
  venue,
  scorers,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  // Meta header
  const mProg    = spring({ frame: frame - META_START, fps, config: SPRINGS.header });
  const mOpacity = interpolate(mProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const mY       = interpolate(mProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  // Card
  const cProg    = spring({ frame: frame - CARD_START, fps, config: SPRINGS.feature });
  const cOpacity = interpolate(cProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const cScale   = interpolate(cProg, [0, 1], [0.94, 1], { extrapolateRight: "clamp" });

  // Score count-up — slow linear climb over 150 frames (5 seconds)
  const scoreProgress = interpolate(frame, [SCORE_START, SCORE_START + 150], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const homeCount = Math.round(interpolate(scoreProgress, [0, 1], [0, homeScore], { extrapolateRight: "clamp" }));
  const awayCount = Math.round(interpolate(scoreProgress, [0, 1], [0, awayScore], { extrapolateRight: "clamp" }));

  // Scorers
  const scProg    = spring({ frame: frame - SCORER_START, fps, config: SPRINGS.cols });
  const scOpacity = interpolate(scProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  const [hr, hg, hb] = hexToRgb(homeColor);
  const [ar, ag, ab] = hexToRgb(awayColor);

  const isHomeWin = homeScore > awayScore;
  const isAwayWin = awayScore > homeScore;

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        {/* Meta header */}
        <div
          style={{
            opacity: mOpacity,
            transform: `translateY(${mY}px)`,
            textAlign: "center",
            marginBottom: 40,
          }}
        >
          <div style={{ fontSize: 22, fontWeight: 700, letterSpacing: 2, color: COLORS.muted, textTransform: "uppercase", fontFamily }}>
            {competition}
          </div>
          <div style={{ fontSize: 28, fontWeight: 500, color: COLORS.secondary, fontFamily, marginTop: 10 }}>
            {date}{venue ? ` · ${venue}` : ""}
          </div>
        </div>

        {/* Score card */}
        <Card
          style={{
            opacity: cOpacity,
            transform: `scale(${cScale})`,
            padding: "48px 80px",
            display: "flex",
            alignItems: "center",
            gap: 64,
            minWidth: 900,
          }}
        >
          {/* Home team */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 16, flex: 1 }}>
            <div
              style={{
                width: 140,
                height: 140,
                borderRadius: 24,
                backgroundColor: rgbaFromHex(homeColor, 0.08),
                border: `2px solid ${rgbaFromHex(homeColor, isHomeWin ? 0.3 : 0.15)}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: isHomeWin ? `0 8px 32px rgba(${hr},${hg},${hb},0.25)` : "none",
              }}
            >
              <img src={staticFile(`badges/${homeBadgeSlug}`)} width={100} height={100} style={{ objectFit: "contain" }} />
            </div>
            <div style={{ fontSize: 22, fontWeight: isHomeWin ? 700 : 600, color: isHomeWin ? COLORS.primary : COLORS.secondary, fontFamily, textAlign: "center", letterSpacing: -0.3 }}>
              {homeTeam}
            </div>
          </div>

          {/* Score */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
              <span
                style={{
                  fontSize: 110,
                  fontWeight: 900,
                  color: isHomeWin ? COLORS.primary : COLORS.secondary,
                  fontFamily,
                  lineHeight: 1,
                  letterSpacing: -4,
                  filter: isHomeWin ? "none" : "opacity(0.5)",
                }}
              >
                {homeCount}
              </span>
              <span style={{ fontSize: 60, fontWeight: 300, color: COLORS.muted, fontFamily, lineHeight: 1 }}>–</span>
              <span
                style={{
                  fontSize: 110,
                  fontWeight: 900,
                  color: isAwayWin ? COLORS.primary : COLORS.secondary,
                  fontFamily,
                  lineHeight: 1,
                  letterSpacing: -4,
                  filter: isAwayWin ? "none" : "opacity(0.5)",
                }}
              >
                {awayCount}
              </span>
            </div>
            <div style={{ width: "100%", height: 2, backgroundColor: COLORS.divider, borderRadius: 1 }} />
            <div style={{ fontSize: 13, fontWeight: 600, letterSpacing: 1.5, color: COLORS.muted, textTransform: "uppercase", fontFamily }}>
              {homeScore === awayScore ? "Draw" : "Full Time"}
            </div>
          </div>

          {/* Away team */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 16, flex: 1 }}>
            <div
              style={{
                width: 140,
                height: 140,
                borderRadius: 24,
                backgroundColor: rgbaFromHex(awayColor, 0.08),
                border: `2px solid ${rgbaFromHex(awayColor, isAwayWin ? 0.3 : 0.15)}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: isAwayWin ? `0 8px 32px rgba(${ar},${ag},${ab},0.25)` : "none",
              }}
            >
              <img src={staticFile(`badges/${awayBadgeSlug}`)} width={100} height={100} style={{ objectFit: "contain" }} />
            </div>
            <div style={{ fontSize: 22, fontWeight: isAwayWin ? 700 : 600, color: isAwayWin ? COLORS.primary : COLORS.secondary, fontFamily, textAlign: "center", letterSpacing: -0.3 }}>
              {awayTeam}
            </div>
          </div>
        </Card>

        {/* Scorers list */}
        {scorers && scorers.length > 0 && (
          <div
            style={{
              opacity: scOpacity,
              marginTop: 32,
              display: "flex",
              gap: 24,
              flexWrap: "wrap",
              justifyContent: "center",
            }}
          >
            {scorers.map((s, i) => (
              <div
                key={i}
                style={{
                  fontSize: 20,
                  fontWeight: 600,
                  color: COLORS.primary,
                  fontFamily,
                  backgroundColor: COLORS.card,
                  borderRadius: 10,
                  padding: "10px 20px",
                  border: `1px solid ${COLORS.cardBorder}`,
                }}
              >
                ⚽ {s}
              </div>
            ))}
          </div>
        )}

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
