/**
 * SeasonComparison — Side-by-side comparison of a player's stats across two seasons.
 * Each stat row has a bar chart that fills proportionally to the higher value.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Card,
  Overline,
  DisplayTitle,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const CompStatSchema = z.object({
  label:   z.string(),
  valueA:  z.number(),
  valueB:  z.number(),
  suffix:  z.string().optional(), // e.g. "%" or " mins"
});

export const SeasonComparisonPropsSchema = z.object({
  playerName:  z.string(),
  badgeSlug:   z.string(),
  clubColor:   z.string(),
  seasonA:     z.string(),           // e.g. "2012–13"
  seasonB:     z.string(),           // e.g. "2013–14"
  colorA:      z.string().optional(), // defaults to clubColor
  colorB:      z.string().optional(), // defaults to muted
  stats:       z.array(CompStatSchema),
});

export type CompStat              = z.infer<typeof CompStatSchema>;
export type SeasonComparisonProps = z.infer<typeof SeasonComparisonPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const HEADER_START = 0;
const ROW_START    = 28;
const ROW_STAGGER  = 10;

// ── Stat Row ──────────────────────────────────────────────────────────────────
const StatRow: React.FC<{
  stat: CompStat;
  index: number;
  frame: number;
  fps: number;
  colorA: string;
  colorB: string;
}> = ({ stat, index, frame, fps, colorA, colorB }) => {
  const delay   = ROW_START + index * ROW_STAGGER;
  const prog    = spring({ frame: frame - delay, fps, config: SPRINGS.row });
  const opacity = interpolate(prog, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const barFill = Math.min(Math.max(prog, 0), 1);

  const maxVal = Math.max(stat.valueA, stat.valueB, 1);
  const wA     = (stat.valueA / maxVal) * barFill;
  const wB     = (stat.valueB / maxVal) * barFill;
  const winA   = stat.valueA > stat.valueB;
  const winB   = stat.valueB > stat.valueA;

  const [rA, gA, bA] = hexToRgb(colorA);
  const [rB, gB, bB] = hexToRgb(colorB);

  const fmt = (v: number) => `${v}${stat.suffix ?? ""}`;

  return (
    <div
      style={{
        opacity,
        display: "flex",
        alignItems: "center",
        gap: 0,
        height: 64,
        borderBottom: `1px solid ${COLORS.divider}`,
      }}
    >
      {/* Season A value */}
      <div style={{ width: 90, textAlign: "right", paddingRight: 16 }}>
        <span
          style={{
            fontSize: winA ? 26 : 22,
            fontWeight: winA ? 800 : 500,
            color: winA ? colorA : COLORS.secondary,
            fontFamily,
            letterSpacing: -0.5,
          }}
        >
          {fmt(stat.valueA)}
        </span>
      </div>

      {/* Bar A (right-aligned, grows left) */}
      <div style={{ flex: 1, display: "flex", justifyContent: "flex-end", height: 8 }}>
        <div
          style={{
            width: `${wA * 100}%`,
            maxWidth: "100%",
            height: "100%",
            borderRadius: "4px 0 0 4px",
            backgroundColor: colorA,
            boxShadow: winA ? `0 0 8px 2px rgba(${rA},${gA},${bA},0.4)` : "none",
          }}
        />
      </div>

      {/* Centre label */}
      <div
        style={{
          width: 160,
          textAlign: "center",
          flexShrink: 0,
          padding: "0 12px",
        }}
      >
        <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: 1.5, color: COLORS.muted, textTransform: "uppercase", fontFamily }}>
          {stat.label}
        </div>
      </div>

      {/* Bar B (left-aligned, grows right) */}
      <div style={{ flex: 1, height: 8 }}>
        <div
          style={{
            width: `${wB * 100}%`,
            maxWidth: "100%",
            height: "100%",
            borderRadius: "0 4px 4px 0",
            backgroundColor: colorB,
            boxShadow: winB ? `0 0 8px 2px rgba(${rB},${gB},${bB},0.4)` : "none",
          }}
        />
      </div>

      {/* Season B value */}
      <div style={{ width: 90, textAlign: "left", paddingLeft: 16 }}>
        <span
          style={{
            fontSize: winB ? 26 : 22,
            fontWeight: winB ? 800 : 500,
            color: winB ? colorB : COLORS.secondary,
            fontFamily,
            letterSpacing: -0.5,
          }}
        >
          {fmt(stat.valueB)}
        </span>
      </div>
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const SeasonComparison: React.FC<SeasonComparisonProps> = ({
  playerName,
  badgeSlug,
  clubColor,
  seasonA,
  seasonB,
  colorA,
  colorB,
  stats,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const resolvedA = colorA ?? clubColor;
  const resolvedB = colorB ?? "#888888";

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: SPRINGS.header });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const [r, g, b] = hexToRgb(clubColor);

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: 100,
          paddingRight: 100,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        {/* Header */}
        <div
          style={{
            opacity: hOpacity,
            transform: `translateY(${hY}px)`,
            display: "flex",
            alignItems: "center",
            gap: 32,
            marginBottom: 36,
          }}
        >
          <div
            style={{
              width: 84,
              height: 84,
              borderRadius: 16,
              backgroundColor: rgbaFromHex(clubColor, 0.1),
              border: `2px solid ${rgbaFromHex(clubColor, 0.2)}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: `0 6px 24px rgba(${r},${g},${b},0.2)`,
              flexShrink: 0,
            }}
          >
            <img src={staticFile(`badges/${badgeSlug}`)} width={58} height={58} style={{ objectFit: "contain" }} />
          </div>
          <div>
            <Overline>Season Comparison</Overline>
            <DisplayTitle size={58}>{playerName}</DisplayTitle>
          </div>
        </div>

        {/* Card with legend + rows */}
        <Card style={{ padding: "24px 32px" }}>
          {/* Season labels / legend */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              marginBottom: 16,
              opacity: hOpacity,
            }}
          >
            {/* Season A label */}
            <div style={{ width: 90, display: "flex", justifyContent: "flex-end", paddingRight: 16 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ width: 10, height: 10, borderRadius: "50%", backgroundColor: resolvedA }} />
                <span style={{ fontSize: 13, fontWeight: 700, color: COLORS.secondary, fontFamily }}>{seasonA}</span>
              </div>
            </div>
            <div style={{ flex: 1 }} />
            <div style={{ width: 160, textAlign: "center" }}>
              <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 1.5, color: COLORS.muted, textTransform: "uppercase", fontFamily }}>
                Stat
              </span>
            </div>
            <div style={{ flex: 1 }} />
            {/* Season B label */}
            <div style={{ width: 90, paddingLeft: 16 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ width: 10, height: 10, borderRadius: "50%", backgroundColor: resolvedB }} />
                <span style={{ fontSize: 13, fontWeight: 700, color: COLORS.secondary, fontFamily }}>{seasonB}</span>
              </div>
            </div>
          </div>

          {stats.map((stat, i) => (
            <StatRow
              key={stat.label}
              stat={stat}
              index={i}
              frame={frame}
              fps={fps}
              colorA={resolvedA}
              colorB={resolvedB}
            />
          ))}
        </Card>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
