/**
 * TrophyGraphic — Honour/trophy celebration card.
 * Large trophy icon, club badge, trophy name, year, and glowing gold treatment.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const TrophyGraphicPropsSchema = z.object({
  trophyName:  z.string(),         // e.g. "Premier League"
  trophyYear:  z.string(),         // e.g. "2013–14"
  clubName:    z.string(),
  badgeSlug:   z.string(),
  clubColor:   z.string(),
  subtext:     z.string().optional(), // e.g. "Champions · 86 Points"
  trophyCount: z.number().optional(), // e.g. 5 (render n trophies for repeat winners)
});

export type TrophyGraphicProps = z.infer<typeof TrophyGraphicPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const GLOW_START   = 0;
const TROPHY_START = 10;
const BADGE_START  = 30;
const NAME_START   = 55;
const SUB_START    = 80;

// ── Large trophy SVG ──────────────────────────────────────────────────────────
const LargeTrophy: React.FC<{ size: number; opacity: number; scale: number }> = ({ size, opacity, scale }) => (
  <div style={{ opacity, transform: `scale(${scale})` }}>
    <svg width={size} height={size} viewBox="0 0 100 100" fill="none">
      <path d="M28 8h44v30a22 22 0 01-44 0V8z" fill={COLORS.gold} />
      <path d="M36 62h28M50 62V78M36 78h28" stroke={COLORS.gold} strokeWidth="4" strokeLinecap="round" />
      <path d="M28 16H14v10a14 14 0 0014 14" stroke={COLORS.gold} strokeWidth="4" strokeLinecap="round" />
      <path d="M72 16h14v10a14 14 0 01-14 14" stroke={COLORS.gold} strokeWidth="4" strokeLinecap="round" />
      <ellipse cx="50" cy="85" rx="18" ry="5" fill={COLORS.gold} opacity={0.4} />
    </svg>
  </div>
);

// ── Radial gold glow ──────────────────────────────────────────────────────────
const GoldGlow: React.FC<{ opacity: number }> = ({ opacity }) => (
  <AbsoluteFill
    style={{
      background: "radial-gradient(ellipse at center, rgba(232,217,165,0.22) 0%, transparent 65%)",
      opacity,
      pointerEvents: "none",
    }}
  />
);

// ── Main composition ───────────────────────────────────────────────────────────
export const TrophyGraphic: React.FC<TrophyGraphicProps> = ({
  trophyName,
  trophyYear,
  clubName,
  badgeSlug,
  clubColor,
  subtext,
  trophyCount = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const mkProg = (start: number, cfg: { damping: number; stiffness: number; mass: number } = SPRINGS.feature) =>
    spring({ frame: frame - start, fps, config: cfg });

  const glowProg   = mkProg(GLOW_START, SPRINGS.header);
  const trophyProg = mkProg(TROPHY_START, SPRINGS.bounce);
  const badgeProg  = mkProg(BADGE_START);
  const nameProg   = mkProg(NAME_START, SPRINGS.header);
  const subProg    = mkProg(SUB_START, SPRINGS.cols);

  const op = (p: ReturnType<typeof spring>, max = 1) =>
    interpolate(p, [0, 0.4], [0, max], { extrapolateRight: "clamp" });
  const sc = (p: ReturnType<typeof spring>, from = 0.7) =>
    interpolate(p, [0, 1], [from, 1], { extrapolateRight: "clamp" });
  const ty = (p: ReturnType<typeof spring>, dist = 24) =>
    interpolate(p, [0, 1], [dist, 0], { extrapolateRight: "clamp" });

  const [r, g, b] = hexToRgb(clubColor);

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />

      {/* Gold glow behind trophy */}
      <GoldGlow opacity={op(glowProg)} />

      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
          gap: 0,
        }}
      >
        {/* Trophy */}
        <LargeTrophy
          size={180}
          opacity={op(trophyProg)}
          scale={sc(trophyProg, 0.6)}
        />

        {/* Club badge */}
        <div
          style={{
            opacity: op(badgeProg),
            transform: `scale(${sc(badgeProg, 0.85)})`,
            marginTop: 28,
            width: 110,
            height: 110,
            borderRadius: 20,
            backgroundColor: rgbaFromHex(clubColor, 0.1),
            border: `2px solid ${rgbaFromHex(clubColor, 0.3)}`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: `0 8px 36px rgba(${r},${g},${b},0.3)`,
          }}
        >
          <img src={staticFile(`badges/${badgeSlug}`)} width={78} height={78} style={{ objectFit: "contain" }} />
        </div>

        {/* Club name + trophy title */}
        <div
          style={{
            opacity: op(nameProg),
            transform: `translateY(${ty(nameProg)}px)`,
            textAlign: "center",
            marginTop: 24,
          }}
        >
          <div
            style={{
              fontSize: 18,
              fontWeight: 600,
              color: COLORS.muted,
              fontFamily,
              letterSpacing: 0.5,
              marginBottom: 8,
            }}
          >
            {clubName}
          </div>
          <div
            style={{
              fontSize: 64,
              fontWeight: 900,
              color: COLORS.primary,
              fontFamily,
              letterSpacing: -2,
              lineHeight: 0.95,
            }}
          >
            {trophyName}
          </div>
          <div
            style={{
              fontSize: 36,
              fontWeight: 300,
              color: COLORS.secondary,
              fontFamily,
              letterSpacing: -0.5,
              marginTop: 8,
            }}
          >
            {trophyYear}
          </div>
        </div>

        {/* Subtext / stats pill */}
        {subtext && (
          <div
            style={{
              opacity: op(subProg),
              transform: `translateY(${ty(subProg, 14)}px)`,
              marginTop: 28,
              backgroundColor: COLORS.champion.pill,
              borderRadius: 10,
              padding: "10px 28px",
              boxShadow: `0 0 20px 5px ${COLORS.champion.glow}`,
            }}
          >
            <span
              style={{
                fontSize: 17,
                fontWeight: 700,
                color: COLORS.primary,
                fontFamily,
                letterSpacing: 0.3,
              }}
            >
              {subtext}
            </span>
          </div>
        )}

        {/* Repeat-winner mini trophies */}
        {trophyCount > 1 && (
          <div
            style={{
              opacity: op(subProg),
              display: "flex",
              gap: 8,
              marginTop: 20,
            }}
          >
            {Array.from({ length: Math.min(trophyCount, 10) }).map((_, i) => (
              <svg key={i} width={20} height={20} viewBox="0 0 100 100" fill="none">
                <path d="M28 8h44v30a22 22 0 01-44 0V8z" fill={COLORS.gold} opacity={0.7} />
              </svg>
            ))}
          </div>
        )}

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
