import React from "react";
import { AbsoluteFill, Img, staticFile, useCurrentFrame, interpolate, spring, useVideoConfig } from "remotion";
import { z } from "zod";
import { DocumentaryFrame } from "./shared";

export const PlayerComparisonPropsSchema = z.object({
  player1Name: z.string(),
  player2Name: z.string(),
  player1Stat: z.string(),
  player2Stat: z.string(),
  player1Image: z.string(),
  player2Image: z.string(),
  player1Color: z.string().optional(),
  player2Color: z.string().optional(),
  title: z.string().optional(),
  subtitle: z.string().optional(),
});

export type PlayerComparisonProps = z.infer<typeof PlayerComparisonPropsSchema>;

export const PlayerComparison: React.FC<PlayerComparisonProps> = ({
  player1Name = "Luis Suárez",
  player2Name = "Sergio Agüero",
  player1Stat = "32 goals • 2013/14",
  player2Stat = "26 goals • 2014/15",
  player1Image = "suarez.jpg",
  player2Image = "aguero.png",
  player1Color = "#E31B23", // Liverpool red
  player2Color = "#6CABDD", // Man City blue
  title = "WHO WAS BETTER?",
  subtitle = "Prime vs Prime • Premier League Legends",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animations
  const leftSlide = spring({ 
    frame: frame - 5, 
    fps, 
    config: { mass: 0.8, damping: 15 },
    durationInFrames: 30 
  });
  
  const rightSlide = spring({ 
    frame: frame - 10, 
    fps, 
    config: { mass: 0.8, damping: 15 },
    durationInFrames: 30 
  });

  const vsScale = spring({ 
    frame: frame - 20, 
    fps, 
    config: { mass: 0.5, damping: 12 },
    durationInFrames: 25 
  });

  const titleOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [0, 15], [-20, 0], { extrapolateRight: "clamp" });

  const leftX = interpolate(leftSlide, [0, 1], [-100, 0]);
  const rightX = interpolate(rightSlide, [0, 1], [100, 0]);
  const vsScaleValue = interpolate(vsScale, [0, 1], [0, 1]);

  return (
    <DocumentaryFrame>
      {/* Background gradient */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        background: "radial-gradient(circle at 50% 50%, #1A1A1A 0%, #0A0A0A 100%)",
      }} />

      {/* Title */}
      <div style={{
        position: "absolute",
        top: 120,
        left: "50%",
        transform: `translateX(-50%) translateY(${titleY}px)`,
        textAlign: "center",
        opacity: titleOpacity,
        zIndex: 10,
      }}>
        <div style={{ 
          fontSize: 48, 
          fontWeight: 800, 
          color: "#fff",
          textTransform: "uppercase",
          letterSpacing: "-0.5px",
          textShadow: "0 2px 10px rgba(0,0,0,0.5)",
        }}>
          {title}
        </div>
        <div style={{ 
          fontSize: 20, 
          fontWeight: 400, 
          color: "#888",
          marginTop: 8,
          letterSpacing: "1px",
        }}>
          {subtitle}
        </div>
      </div>

      {/* Player 1 - Left (Suárez) */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "25%",
        transform: `translate(calc(-50% + ${leftX}px), -50%)`,
        textAlign: "center",
        zIndex: 5,
      }}>
        {/* Image container with glow */}
        <div style={{
          position: "relative",
          width: 240,
          height: 240,
          marginBottom: 20,
        }}>
          {/* Glow effect */}
          <div style={{
            position: "absolute",
            top: -10,
            left: -10,
            right: -10,
            bottom: -10,
            borderRadius: "50%",
            background: `radial-gradient(circle, ${player1Color}80 0%, transparent 70%)`,
            filter: "blur(15px)",
            opacity: 0.6,
          }} />
          
          {/* Image */}
          <Img
            src={staticFile(player1Image)}
            style={{
              width: "100%",
              height: "100%",
              borderRadius: "50%",
              objectFit: "cover",
              border: `4px solid ${player1Color}`,
              boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
              position: "relative",
              zIndex: 2,
            }}
          />
        </div>

        {/* Name */}
        <div style={{
          fontSize: 42,
          fontWeight: 800,
          color: "#fff",
          textTransform: "uppercase",
          letterSpacing: "-0.5px",
          marginBottom: 8,
          textShadow: "0 2px 5px rgba(0,0,0,0.5)",
        }}>
          {player1Name}
        </div>

        {/* Stat */}
        <div style={{
          fontSize: 24,
          fontWeight: 500,
          color: player1Color,
          backgroundColor: "rgba(0,0,0,0.6)",
          padding: "8px 20px",
          borderRadius: 40,
          display: "inline-block",
          border: `1px solid ${player1Color}40`,
          backdropFilter: "blur(5px)",
        }}>
          {player1Stat}
        </div>
      </div>

      {/* VS Circle */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: `translate(-50%, -50%) scale(${vsScaleValue})`,
        width: 80,
        height: 80,
        borderRadius: "50%",
        background: "linear-gradient(135deg, #fff, #f0f0f0)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        boxShadow: "0 10px 30px rgba(0,0,0,0.3), 0 0 0 4px rgba(255,255,255,0.1)",
        zIndex: 20,
      }}>
        <span style={{
          fontSize: 28,
          fontWeight: 900,
          color: "#0A0A0A",
          letterSpacing: "-0.5px",
        }}>
          VS
        </span>
      </div>

      {/* Player 2 - Right (Agüero) */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "75%",
        transform: `translate(calc(-50% - ${rightX}px), -50%)`,
        textAlign: "center",
        zIndex: 5,
      }}>
        {/* Image container with glow */}
        <div style={{
          position: "relative",
          width: 240,
          height: 240,
          marginBottom: 20,
        }}>
          {/* Glow effect */}
          <div style={{
            position: "absolute",
            top: -10,
            left: -10,
            right: -10,
            bottom: -10,
            borderRadius: "50%",
            background: `radial-gradient(circle, ${player2Color}80 0%, transparent 70%)`,
            filter: "blur(15px)",
            opacity: 0.6,
          }} />
          
          {/* Image */}
          <Img
            src={staticFile(player2Image)}
            style={{
              width: "100%",
              height: "100%",
              borderRadius: "50%",
              objectFit: "cover",
              border: `4px solid ${player2Color}`,
              boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
              position: "relative",
              zIndex: 2,
            }}
          />
        </div>

        {/* Name */}
        <div style={{
          fontSize: 42,
          fontWeight: 800,
          color: "#fff",
          textTransform: "uppercase",
          letterSpacing: "-0.5px",
          marginBottom: 8,
          textShadow: "0 2px 5px rgba(0,0,0,0.5)",
        }}>
          {player2Name}
        </div>

        {/* Stat */}
        <div style={{
          fontSize: 24,
          fontWeight: 500,
          color: player2Color,
          backgroundColor: "rgba(0,0,0,0.6)",
          padding: "8px 20px",
          borderRadius: 40,
          display: "inline-block",
          border: `1px solid ${player2Color}40`,
          backdropFilter: "blur(5px)",
        }}>
          {player2Stat}
        </div>
      </div>

      {/* Bottom decorative line */}
      <div style={{
        position: "absolute",
        bottom: 60,
        left: "50%",
        transform: "translateX(-50%)",
        width: 200,
        height: 2,
        background: "linear-gradient(90deg, transparent, #fff, transparent)",
        opacity: 0.3,
      }} />

      {/* Brand mark */}
      <div style={{
        position: "absolute",
        bottom: 30,
        right: 40,
        fontSize: 12,
        fontWeight: 300,
        color: "#666",
        letterSpacing: "2px",
        textTransform: "uppercase",
      }}>
        THE LEGENDS SERIES
      </div>
    </DocumentaryFrame>
  );
};