import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import { DocumentaryFrame } from "./shared";
import { loadFont } from "@remotion/google-fonts/Inter";

const { fontFamily } = loadFont("normal", {
  weights: ["400", "500", "600", "700", "800", "900"],
});

export const TeamSchema = z.object({
  pos:       z.number(),
  name:      z.string(),
  color:     z.string(),
  badgeSlug: z.string(),
  p:  z.number(),
  w:  z.number(),
  d:  z.number(),
  l:  z.number(),
  gd: z.number(),
  pts: z.number(),
});

export const TablePropsSchema = z.object({
  teams:  z.array(TeamSchema),
  season: z.string(),
});

export type Team       = z.infer<typeof TeamSchema>;
export type TableProps = z.infer<typeof TablePropsSchema>;

// ── Timing (frames @ 30fps) ───────────────────────────────────────────────────
// Bottom-to-top reveal: Tottenham (idx 5) first → Man City (idx 0) last
const HEADER_START = 0;
const COLS_START   = 20;
const ROW_START    = 30;
const ROW_STAGGER  = 9;

const headerSpr = { damping: 18, stiffness: 55, mass: 1 };
const rowSpr    = { damping: 13, stiffness: 140, mass: 1 };
const colsSpr   = { damping: 20, stiffness: 80,  mass: 1 };

// ── Film grain ────────────────────────────────────────────────────────────────
const Grain: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const seed = frame % 120;
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
        <defs>
          <filter id={`g${seed}`} x="0" y="0" width="100%" height="100%">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.82"
              numOctaves="4"
              seed={seed}
              stitchTiles="stitch"
            />
            <feColorMatrix
              type="matrix"
              values="0.38 0.5  0.12 0 0
                      0.28 0.58 0.14 0 0
                      0.22 0.5  0.28 0 0
                      0    0    0    0 0.05"
            />
          </filter>
        </defs>
        <rect width={width} height={height} filter={`url(#g${seed})`} />
      </svg>
    </AbsoluteFill>
  );
};

// ── Vignette ──────────────────────────────────────────────────────────────────
const Vignette: React.FC = () => (
  <AbsoluteFill
    style={{
      background: "radial-gradient(circle at center, transparent 60%, rgba(0,0,0,0.05) 100%)",
      pointerEvents: "none",
    }}
  />
);

// ── Trophy ────────────────────────────────────────────────────────────────────
const Trophy: React.FC<{ opacity: number }> = ({ opacity }) => (
  <div style={{ opacity, marginLeft: 10, display: "flex", alignItems: "center" }}>
    <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
      <path d="M6 2h12v8a6 6 0 01-12 0V2z" fill="#C9A84C" />
      <path d="M9 16.5h6M12 16.5V20M9 20h6" stroke="#C9A84C" strokeWidth="1.6" strokeLinecap="round" />
      <path d="M6 4.5H3.5v2.5a2.5 2.5 0 002.5 2.5" stroke="#C9A84C" strokeWidth="1.5" strokeLinecap="round" />
      <path d="M18 4.5h2.5v2.5a2.5 2.5 0 01-2.5 2.5" stroke="#C9A84C" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  </div>
);

// ── Column header style ───────────────────────────────────────────────────────
const colH = (width: number, color = "#444"): React.CSSProperties => ({
  width: width || undefined,
  fontSize: 12,
  fontWeight: 700,
  color,
  textAlign: "center",
  letterSpacing: 1.5,
  textTransform: "uppercase",
  fontFamily,
  flexShrink: 0,
});

// ── Table Row ─────────────────────────────────────────────────────────────────
const TableRow: React.FC<{ team: Team; index: number; teamsCount: number; frame: number; fps: number }> = ({
  team,
  index,
  teamsCount,
  frame,
  fps,
}) => {
  const delay      = ROW_START + (teamsCount - 1 - index) * ROW_STAGGER;
  const prog       = spring({ frame: frame - delay, fps, config: rowSpr });
  const rawOpacity = interpolate(prog, [0, 0.35], [0, 1], { extrapolateRight: "clamp" });
  const opacity    = rawOpacity;
  const transY     = interpolate(prog, [0, 1], [24, 0], { extrapolateRight: "clamp" });

  // Points count-up
  const clamped    = Math.min(Math.max(prog, 0), 1);
  const countedPts = Math.round(
    interpolate(clamped, [0, 0.85], [0, team.pts], { extrapolateRight: "clamp" })
  );

  const isChampion = team.pos === 1;
  const isTopTwo   = team.pos <= 2;

  const trophyProg    = spring({ frame: frame - (delay + 9), fps, config: { damping: 20, stiffness: 60, mass: 1 } });
  const trophyOpacity = isChampion
    ? interpolate(trophyProg, [0, 1], [0, 1], { extrapolateRight: "clamp" })
    : 0;

  const [r, g, b] = hexToRgb(team.color);

  // Champion row: muted gold
  const rowBg     = isChampion ? "rgba(232, 217, 165, 0.45)" : index % 2 === 0 ? "rgba(0,0,0,0.025)" : "transparent";
  const rowShadow = isChampion ? "0 6px 28px rgba(232, 217, 165, 0.4)" : "0 2px 8px rgba(0,0,0,0.04)";

  // Points pill — 10% bigger across the board
  const ptsBg     = isChampion ? "#e8d9a5" : isTopTwo ? `rgba(${r},${g},${b},0.14)` : "#ddd8d0";
  const ptsFontSz = isChampion ? 31 : isTopTwo ? 26 : 25;
  const ptsWidth  = isChampion ? 82 : 74;
  const ptsGlow   = isChampion ? "0 0 20px 6px rgba(232, 217, 165, 0.55)" : "none";

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        height: 86,
        backgroundColor: rowBg,
        borderRadius: 12,
        marginBottom: 4,
        opacity,
        transform: `translateY(${transY}px)`,
        position: "relative",
        paddingLeft: 16,
        paddingRight: 20,
        boxShadow: rowShadow,
        overflow: "hidden",
      }}
    >
      {/* Subtle top highlight — gives rows dimension without washing out content */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "linear-gradient(180deg, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0) 50%)",
          pointerEvents: "none",
        }}
      />

      {/* Left accent bar with glow */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 18,
          bottom: 18,
          width: 5,
          borderRadius: 3,
          backgroundColor: team.color,
          boxShadow: `0 0 14px 4px rgba(${r},${g},${b},0.4)`,
        }}
      />

      {/* Club badge */}
      <div
        style={{
          width: 66,
          height: 66,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexShrink: 0,
          marginLeft: 10,
        }}
      >
        <img
          src={staticFile(`badges/${team.badgeSlug}`)}
          width={60}
          height={60}
          style={{ objectFit: "contain" }}
        />
      </div>

      {/* Position */}
      <div
        style={{
          width: 38,
          fontSize: 24,
          fontWeight: 800,
          color: "#111",
          fontFamily,
          textAlign: "center",
          letterSpacing: -0.5,
          marginLeft: 8,
          flexShrink: 0,
        }}
      >
        {team.pos}
      </div>

      {/* Team name + optional trophy */}
      <div style={{ flex: 1, display: "flex", alignItems: "center", paddingLeft: 18 }}>
        <span
          style={{
            fontSize: 21,
            fontWeight: isChampion ? 700 : 600,
            color: "#111",
            fontFamily,
            letterSpacing: -0.2,
          }}
        >
          {team.name}
        </span>
        {isChampion && <Trophy opacity={trophyOpacity} />}
      </div>

      {/* Stats: P W D L GD */}
      {[team.p, team.w, team.d, team.l, team.gd >= 0 ? `+${team.gd}` : String(team.gd)].map(
        (val, i) => (
          <div
            key={i}
            style={{
              width: 60,
              textAlign: "center",
              fontSize: 17,
              fontWeight: 500,
              color: "#444",
              fontFamily,
              flexShrink: 0,
            }}
          >
            {val}
          </div>
        )
      )}

      {/* Points — count-up, glow for champion, tint for top 2 */}
      <div
        style={{
          width: ptsWidth,
          textAlign: "center",
          fontSize: ptsFontSz,
          fontWeight: 800,
          color: "#111",
          fontFamily,
          backgroundColor: ptsBg,
          borderRadius: 10,
          paddingTop: 9,
          paddingBottom: 9,
          letterSpacing: -0.5,
          flexShrink: 0,
          boxShadow: ptsGlow,
        }}
      >
        {countedPts}
      </div>
    </div>
  );
};

// ── Main composition ──────────────────────────────────────────────────────────
export const PremierLeagueTable: React.FC<TableProps> = ({ teams, season }) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale   = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale  = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDriftY = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: headerSpr });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const cProg    = spring({ frame: frame - COLS_START, fps, config: colsSpr });
  const cOpacity = interpolate(cProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  return (
    <DocumentaryFrame>

      {/* ── Background ── */}
      <AbsoluteFill
        style={{
          background: "linear-gradient(155deg, #f5f0e8 0%, #e9e2d8 100%)",
          transform: `scale(${bgScale})`,
          transformOrigin: "center center",
        }}
      />

      <Grain />
      <Vignette />

      {/* ── Content ── */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: 100,
          transform: `scale(${cntScale}) translateY(${cntDriftY}px)`,
          transformOrigin: "center center",
        }}
      >
        <div style={{ width: 1440 }}>

          {/* ── Title block ── */}
          <div
            style={{
              opacity: hOpacity,
              transform: `translateY(${hY}px)`,
              marginBottom: 32,
              display: "flex",
              alignItems: "center",
              gap: 32,
            }}
          >
            {/* PL logo */}
            <img
              src={staticFile("badges/premier-league.svg")}
              width={84}
              height={84}
              style={{ objectFit: "contain", flexShrink: 0 }}
            />

            <div>
            <div
              style={{
                fontSize: 15,
                fontWeight: 700,
                letterSpacing: 2,
                color: "#111",
                textTransform: "uppercase",
                marginBottom: 6,
                fontFamily,
              }}
            >
              Premier League
            </div>
            <div
              style={{
                fontSize: 68,
                fontWeight: 900,
                color: "#111",
                lineHeight: 0.95,
                letterSpacing: -2,
                fontFamily,
              }}
            >
              {season} Season
            </div>
            <div
              style={{
                fontSize: 15,
                fontWeight: 400,
                color: "#999",
                marginTop: 10,
                letterSpacing: 0.3,
                fontFamily,
              }}
            >
              Final Standings
            </div>
            </div>
          </div>

          {/* ── Table card ── */}
          <div
            style={{
              backgroundColor: "#eae4dc",
              borderRadius: 16,
              border: "1px solid rgba(0,0,0,0.07)",
              padding: "18px 24px 16px",
              boxShadow: "0px 20px 60px rgba(0,0,0,0.1), 0 4px 16px rgba(0,0,0,0.05)",
            }}
          >
            {/* Column headers */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                paddingLeft: 16,
                paddingRight: 20,
                paddingBottom: 13,
                borderBottom: "1px solid rgba(0,0,0,0.08)",
                marginBottom: 8,
                opacity: cOpacity,
              }}
            >
              <div style={{ width: 78, flexShrink: 0 }} /> {/* badge spacer */}
              <div style={{ width: 46, flexShrink: 0 }} /> {/* pos spacer */}
              <div style={{ ...colH(0), flex: 1, textAlign: "left" }}>Club</div>
              {["P", "W", "D", "L", "GD", "Pts"].map((col) => (
                <div key={col} style={colH(col === "Pts" ? 72 : 60, col === "Pts" ? "#222" : "#555")}>
                  {col}
                </div>
              ))}
            </div>

            {/* Team rows */}
            {teams.map((team, i) => (
              <TableRow key={team.pos} team={team} index={i} teamsCount={teams.length} frame={frame} fps={fps} />
            ))}
          </div>
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};

// ── Utility ───────────────────────────────────────────────────────────────────
function hexToRgb(hex: string): [number, number, number] {
  return [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16),
  ];
}
