/**
 * ArticleHeadline — Newspaper-style article headline graphic.
 * Adapts the classic news article layout (category tag, accent bar, highlighted
 * headline, byline) to the 90th parchment infographic style.
 *
 * The headline text sits on a colour-highlight band that wipes in from the left.
 * Accent colour matches the club or episode theme.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  hexToRgb,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const ArticleHeadlinePropsSchema = z.object({
  headline:     z.string(),
  category:     z.string().default("Football"),        // e.g. "Transfer News", "Match Report"
  byline:       z.string().optional(),                  // e.g. "Sky Sports"
  date:         z.string().optional(),                  // e.g. "14 July 2014"
  accentColor:  z.string().default("#D3122D"),          // optimized readable red highlight
});

export type ArticleHeadlineProps = z.infer<typeof ArticleHeadlinePropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const BAR_START      = 0;
const CATEGORY_START = 10;
const HEADLINE_START = 22;
const BYLINE_START   = 55;

// ── Main composition ───────────────────────────────────────────────────────────
export const ArticleHeadline: React.FC<ArticleHeadlineProps> = ({
  headline,
  category = "Football",
  byline,
  date,
  accentColor = "#D3122D",
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.015]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -6]);

  const mk = (start: number, cfg = SPRINGS.feature) =>
    spring({ frame: frame - start, fps, config: cfg });

  const barProg      = mk(BAR_START,      SPRINGS.cols);
  const catProg      = mk(CATEGORY_START, SPRINGS.row);
  const headlineProg = mk(HEADLINE_START, SPRINGS.header);
  const bylineProg   = mk(BYLINE_START,   SPRINGS.row);

  // Left bar draws downward
  const barH = interpolate(barProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  // Category slides in from left
  const catOpacity = interpolate(catProg, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
  const catX       = interpolate(catProg, [0, 1],   [-20, 0], { extrapolateRight: "clamp" });

  // Headline highlight wipes in from left, then text fades
  const hlW        = interpolate(headlineProg, [0, 0.7], [0, 1], { extrapolateRight: "clamp" });
  const hlTextOp   = interpolate(headlineProg, [0.25, 0.8], [0, 1], { extrapolateRight: "clamp" });
  const hlScale    = interpolate(headlineProg, [0, 1], [0.98, 1], { extrapolateRight: "clamp" });

  // Byline fades in
  const bylineOp   = interpolate(bylineProg, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
  const bylineX    = interpolate(bylineProg, [0, 1],   [-16, 0], { extrapolateRight: "clamp" });

  const [r, g, b] = hexToRgb(accentColor);

  // Byline string
  const bylineText = [byline, date].filter(Boolean).join("  |  ");

  // Headline font size — scale down for very long headlines
  const hlFontSize = headline.length > 120 ? 52 : headline.length > 80 ? 62 : 72;

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          paddingLeft: 80,
          paddingRight: 80,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        <div style={{ width: "100%", maxWidth: 1500 }}>

          {/* Category tag */}
          <div
            style={{
              opacity: catOpacity,
              transform: `translateX(${catX}px)`,
              marginBottom: 28,
              // offset to align with headline (left bar width + gap)
              paddingLeft: 28,
            }}
          >
            <span
              style={{
                fontSize: 14,
                fontWeight: 800,
                color: COLORS.secondary,
                fontFamily,
                letterSpacing: 2.5,
                textTransform: "uppercase",
              }}
            >
              {category}
            </span>
          </div>

          {/* Left bar + headline row */}
          <div style={{ display: "flex", gap: 28, alignItems: "stretch" }}>

            {/* Vertical accent bar */}
            <div
              style={{
                width: 5,
                flexShrink: 0,
                borderRadius: 3,
                backgroundColor: accentColor,
                transformOrigin: "top",
                transform: `scaleY(${barH})`,
                boxShadow: `0 0 14px 4px rgba(${r},${g},${b},0.35)`,
              }}
            />

            {/* Headline block */}
            <div
              style={{
                flex: 1,
                transform: `scale(${hlScale})`,
                transformOrigin: "left center",
              }}
            >
              {/*
                The highlight band is a ::before-style element placed absolutely
                behind the text, wiping in from left to right.
                Because the text naturally wraps, we use inline highlight via
                background on the span with box-decoration-break: clone.
              */}
              <div style={{ position: "relative", display: "inline" }}>
                {/* Wipe mask — covers the highlight from right, shrinks away */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    right: 0,
                    bottom: 0,
                    width: `${(1 - hlW) * 100}%`,
                    backgroundColor: "rgba(245,240,232,1)",   // matches parchment bg
                    zIndex: 2,
                    pointerEvents: "none",
                  }}
                />

                <span
                  style={{
                    fontSize: hlFontSize,
                    fontWeight: 800,
                    color: COLORS.primary,
                    fontFamily,
                    lineHeight: 1.25,
                    letterSpacing: -1,
                    // Inline highlight that wraps across lines
                    backgroundColor: accentColor,
                    WebkitBoxDecorationBreak: "clone",
                    boxDecorationBreak: "clone" as any,
                    padding: "6px 14px",
                    display: "inline",
                    opacity: hlTextOp,
                    position: "relative",
                    zIndex: 1,
                  } as React.CSSProperties}
                >
                  {headline}
                </span>
              </div>

              {/* Byline */}
              {bylineText && (
                <div
                  style={{
                    marginTop: 28,
                    opacity: bylineOp,
                    transform: `translateX(${bylineX}px)`,
                    paddingLeft: 4,
                  }}
                >
                  <span
                    style={{
                      fontSize: 16,
                      fontWeight: 400,
                      color: COLORS.muted,
                      fontFamily,
                      letterSpacing: 0.2,
                    }}
                  >
                    {bylineText}
                  </span>
                </div>
              )}
            </div>
          </div>

        </div>
      </AbsoluteFill>

    </DocumentaryFrame>
  );
};
