/**
 * TransferAnnouncement — FROM club → TO club with player name, fee, and year.
 * Arrow reveals after badges; fee pill drops in last.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Card,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const TransferAnnouncementPropsSchema = z.object({
  playerName:    z.string(),
  fromClub:      z.string(),
  toClub:        z.string(),
  fromBadgeSlug: z.string(),
  toBadgeSlug:   z.string(),
  fromColor:     z.string(),
  toColor:       z.string(),
  fee:           z.string(),           // e.g. "£75m" or "Free Transfer"
  year:          z.string(),           // e.g. "2014"
  nationality:   z.string().optional(),
});

export type TransferAnnouncementProps = z.infer<typeof TransferAnnouncementPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const LABEL_START  = 0;
const FROM_START   = 18;
const ARROW_START  = 45;
const TO_START     = 55;
const NAME_START   = 80;
const FEE_START    = 105;

// ── Arrow SVG ─────────────────────────────────────────────────────────────────
const Arrow: React.FC<{ opacity: number; scale: number }> = ({ opacity, scale }) => (
  <div style={{ opacity, transform: `scale(${scale})`, display: "flex", alignItems: "center" }}>
    <svg width="80" height="40" viewBox="0 0 80 40" fill="none">
      <line x1="0" y1="20" x2="56" y2="20" stroke={COLORS.muted} strokeWidth="2" />
      <polygon points="56,10 80,20 56,30" fill={COLORS.secondary} />
    </svg>
  </div>
);

// ── Club panel ────────────────────────────────────────────────────────────────
const ClubPanel: React.FC<{
  name: string;
  badgeSlug: string;
  color: string;
  label: string;
  opacity: number;
  transX: number;
}> = ({ name, badgeSlug, color, label, opacity, transX }) => {
  const [r, g, b] = hexToRgb(color);
  return (
    <div
      style={{
        opacity,
        transform: `translateX(${transX}px)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 20,
        width: 280,
      }}
    >
      <div
        style={{
          fontSize: 11,
          fontWeight: 700,
          letterSpacing: 2,
          color: COLORS.muted,
          textTransform: "uppercase",
          fontFamily,
        }}
      >
        {label}
      </div>
      <div
        style={{
          width: 160,
          height: 160,
          borderRadius: 28,
          backgroundColor: rgbaFromHex(color, 0.1),
          border: `2px solid ${rgbaFromHex(color, 0.25)}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: `0 12px 40px rgba(${r},${g},${b},0.25)`,
        }}
      >
        <img src={staticFile(`badges/${badgeSlug}`)} width={110} height={110} style={{ objectFit: "contain" }} />
      </div>
      <div
        style={{
          fontSize: 20,
          fontWeight: 700,
          color: COLORS.primary,
          fontFamily,
          textAlign: "center",
          letterSpacing: -0.3,
        }}
      >
        {name}
      </div>
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const TransferAnnouncement: React.FC<TransferAnnouncementProps> = ({
  playerName,
  fromClub,
  toClub,
  fromBadgeSlug,
  toBadgeSlug,
  fromColor,
  toColor,
  fee,
  year,
  nationality,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const mkProg = (start: number, cfg: { damping: number; stiffness: number; mass: number } = SPRINGS.feature) =>
    spring({ frame: frame - start, fps, config: cfg });

  const labelProg = mkProg(LABEL_START, SPRINGS.header);
  const fromProg  = mkProg(FROM_START);
  const arrowProg = mkProg(ARROW_START, SPRINGS.cols);
  const toProg    = mkProg(TO_START);
  const nameProg  = mkProg(NAME_START, SPRINGS.row);
  const feeProg   = mkProg(FEE_START, SPRINGS.bounce);

  const op  = (p: ReturnType<typeof spring>) => interpolate(p, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const txL = (p: ReturnType<typeof spring>) => interpolate(p, [0, 1], [-30, 0], { extrapolateRight: "clamp" });
  const txR = (p: ReturnType<typeof spring>) => interpolate(p, [0, 1], [30, 0],  { extrapolateRight: "clamp" });
  const sc  = (p: ReturnType<typeof spring>) => interpolate(p, [0, 1], [0.85, 1], { extrapolateRight: "clamp" });
  const ty  = (p: ReturnType<typeof spring>) => interpolate(p, [0, 1], [20, 0],  { extrapolateRight: "clamp" });

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
          gap: 0,
        }}
      >
        {/* Transfer label */}
        <div
          style={{
            opacity: op(labelProg),
            transform: `translateY(${ty(labelProg)}px)`,
            marginBottom: 36,
            textAlign: "center",
          }}
        >
          <div style={{ fontSize: 22, fontWeight: 700, letterSpacing: 2, color: COLORS.muted, textTransform: "uppercase", fontFamily }}>
            Transfer
          </div>
          <div style={{ fontSize: 28, fontWeight: 500, color: COLORS.secondary, fontFamily, marginTop: 10 }}>
            {year}
          </div>
        </div>

        {/* Club panels + arrow */}
        <Card style={{ padding: "40px 60px", display: "flex", alignItems: "center", gap: 48 }}>
          <ClubPanel
            name={fromClub}
            badgeSlug={fromBadgeSlug}
            color={fromColor}
            label="From"
            opacity={op(fromProg)}
            transX={txL(fromProg)}
          />

          <Arrow
            opacity={op(arrowProg)}
            scale={sc(arrowProg)}
          />

          <ClubPanel
            name={toClub}
            badgeSlug={toBadgeSlug}
            color={toColor}
            label="To"
            opacity={op(toProg)}
            transX={txR(toProg)}
          />
        </Card>

        {/* Player name */}
        <div
          style={{
            opacity: op(nameProg),
            transform: `translateY(${ty(nameProg)}px)`,
            marginTop: 36,
            textAlign: "center",
          }}
        >
          <div
            style={{
              fontSize: 72,
              fontWeight: 900,
              color: COLORS.primary,
              fontFamily,
              letterSpacing: -2.5,
              lineHeight: 0.95,
            }}
          >
            {playerName}
          </div>
          {nationality && (
            <div style={{ fontSize: 16, fontWeight: 400, color: COLORS.muted, fontFamily, marginTop: 10 }}>
              {nationality}
            </div>
          )}
        </div>

        {/* Fee pill */}
        <div
          style={{
            opacity: op(feeProg),
            transform: `scale(${sc(feeProg)})`,
            marginTop: 28,
            backgroundColor: COLORS.champion.pill,
            borderRadius: 12,
            padding: "12px 36px",
            boxShadow: `0 0 24px 6px ${COLORS.champion.glow}`,
          }}
        >
          <span
            style={{
              fontSize: 28,
              fontWeight: 800,
              color: COLORS.primary,
              fontFamily,
              letterSpacing: -0.5,
            }}
          >
            {fee}
          </span>
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
