/**
 * TopScorersTable — Top N scorers or assisters for a given competition/season.
 * Reuses the exact same row aesthetic as PremierLeagueTable.
 * Composition IDs: "TopScorersTable" and "TopAssistsTable" (same component, different props).
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Card,
  AccentBar,
  RowSheen,
  colH,
  Overline,
  DisplayTitle,
  MetaLine,
  hexToRgb,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const ScorerSchema = z.object({
  pos:       z.number(),
  name:      z.string(),
  club:      z.string(),
  badgeSlug: z.string(),
  clubColor: z.string(),
  goals:     z.number(),
  assists:   z.number().default(0),
  apps:      z.number(),
});

export const TopScorersPropsSchema = z.object({
  players:    z.array(ScorerSchema),
  season:     z.string(),
  competition: z.string().default("Premier League"),
  statLabel:  z.string().default("Goals"),   // "Goals" or "Assists"
  statKey:    z.enum(["goals", "assists"]).default("goals"),
});

export type Scorer          = z.infer<typeof ScorerSchema>;
export type TopScorersProps = z.infer<typeof TopScorersPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const HEADER_START = 0;
const COLS_START   = 20;
const ROW_START    = 30;
const ROW_STAGGER  = 9;

// ── Player Row ─────────────────────────────────────────────────────────────────
const PlayerRow: React.FC<{
  player: Scorer;
  index: number;
  count: number;
  frame: number;
  fps: number;
  statKey: "goals" | "assists";
  topStat: number;
}> = ({ player, index, count, frame, fps, statKey, topStat }) => {
  const delay   = ROW_START + (count - 1 - index) * ROW_STAGGER;
  const prog    = spring({ frame: frame - delay, fps, config: SPRINGS.row });
  const opacity = interpolate(prog, [0, 0.35], [0, 1], { extrapolateRight: "clamp" });
  const transY  = interpolate(prog, [0, 1], [24, 0],   { extrapolateRight: "clamp" });

  const isTop     = player.pos === 1;
  const statValue = statKey === "goals" ? player.goals : player.assists;


  // Stat count-up
  const counted = Math.round(
    interpolate(Math.min(Math.max(prog, 0), 1), [0, 0.85], [0, statValue], {
      extrapolateRight: "clamp",
    })
  );

  const [r, g, b] = hexToRgb(player.clubColor);
  const rowBg     = isTop ? COLORS.champion.rowBg : index % 2 === 0 ? COLORS.rowAlt : "transparent";
  const rowShadow = isTop
    ? "0 6px 28px rgba(232,217,165,0.4)"
    : "0 2px 8px rgba(0,0,0,0.04)";
  
  // Rank 1 keeps the special gold/pill color, others use a modern neutral gray
  const pillBg    = isTop ? COLORS.champion.pill : "#e0e0e0";
  const pillGlow  = isTop ? `0 0 20px 6px ${COLORS.champion.glow}` : "none";

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        height: 86,
        backgroundColor: rowBg,
        borderRadius: 12,
        marginBottom: 4,
        opacity,
        transform: `translateY(${transY}px)`,
        position: "relative",
        paddingLeft: 16,
        paddingRight: 24,
        boxShadow: rowShadow,
        overflow: "hidden",
      }}
    >
      <RowSheen />
      <AccentBar color={player.clubColor} />

      {/* Badge */}
      <div style={{ width: 66, height: 66, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginLeft: 10 }}>
        <img src={staticFile(`badges/${player.badgeSlug}`)} width={60} height={60} style={{ objectFit: "contain" }} />
      </div>

      {/* Rank */}
      <div style={{ width: 38, fontSize: 24, fontWeight: 800, color: COLORS.primary, fontFamily, textAlign: "center", letterSpacing: -0.5, marginLeft: 8, flexShrink: 0 }}>
        {player.pos}
      </div>

      {/* Name + Club */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", paddingLeft: 18 }}>
        <span style={{ fontSize: 21, fontWeight: isTop ? 700 : 600, color: COLORS.primary, fontFamily, letterSpacing: -0.2 }}>
          {player.name}
        </span>
        <span style={{ fontSize: 13, fontWeight: 500, color: COLORS.muted, fontFamily, marginTop: 2 }}>
          {player.club}
        </span>
      </div>



      {/* Apps */}
      <div style={{ width: 60, textAlign: "center", fontSize: 16, fontWeight: 500, color: COLORS.secondary, fontFamily, flexShrink: 0 }}>
        {player.apps}
      </div>

      {/* Stat pill */}
      <div
        style={{
          width: 74,
          textAlign: "center",
          fontSize: isTop ? 31 : 25,
          fontWeight: 800,
          color: COLORS.primary,
          fontFamily,
          backgroundColor: pillBg,
          borderRadius: 10,
          paddingTop: 9,
          paddingBottom: 9,
          letterSpacing: -0.5,
          flexShrink: 0,
          boxShadow: pillGlow,
        }}
      >
        {counted}
      </div>
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const TopScorersTable: React.FC<TopScorersProps> = ({
  players,
  season,
  competition,
  statLabel,
  statKey,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: SPRINGS.header });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const cProg    = spring({ frame: frame - COLS_START, fps, config: SPRINGS.cols });
  const cOpacity = interpolate(cProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  const topStat = Math.max(...players.map(p => statKey === "goals" ? p.goals : p.assists), 1);
  const metaText = statKey === "goals" ? "Top Scorers" : "Most Assists";

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: 100,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        <div style={{ width: 1440 }}>

          {/* Title block */}
          <div style={{ opacity: hOpacity, transform: `translateY(${hY}px)`, marginBottom: 32 }}>
            <Overline>{competition}</Overline>
            <DisplayTitle>{season} Season</DisplayTitle>
            <MetaLine>{metaText}</MetaLine>
          </div>

          {/* Table card */}
          <Card style={{ padding: "18px 24px 16px" }}>
            {/* Column headers */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                paddingLeft: 16,
                paddingRight: 24,
                paddingBottom: 13,
                borderBottom: `1px solid ${COLORS.divider}`,
                marginBottom: 8,
                opacity: cOpacity,
              }}
            >
              <div style={{ width: 78, flexShrink: 0 }} />
              <div style={{ width: 46, flexShrink: 0 }} />
              <div style={{ ...colH(0), flex: 1, textAlign: "left" }}>Player</div>

              <div style={colH(60)}>Apps</div>
              <div style={colH(74, COLORS.colHeaderStrong)}>{statLabel}</div>
            </div>

            {players.map((player, i) => (
              <PlayerRow
                key={player.pos}
                player={player}
                index={i}
                count={players.length}
                frame={frame}
                fps={fps}
                statKey={statKey}
                topStat={topStat}
              />
            ))}
          </Card>
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
