/**
 * CareerTimeline — Horizontal timeline of a player's career clubs/events.
 * Nodes reveal left-to-right with a connecting line drawing in.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Overline,
  DisplayTitle,
  MetaLine,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const TimelineEventSchema = z.object({
  year:      z.string(),          // e.g. "2011" or "2011–14"
  club:      z.string(),
  badgeSlug: z.string(),
  clubColor: z.string(),
  detail:    z.string().optional(), // e.g. "82 goals in 133 apps"
  isHighlight: z.boolean().default(false),
});

export const CareerTimelinePropsSchema = z.object({
  playerName: z.string(),
  events:     z.array(TimelineEventSchema), // 3–7 events works best
});

export type TimelineEvent        = z.infer<typeof TimelineEventSchema>;
export type CareerTimelineProps  = z.infer<typeof CareerTimelinePropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const HEADER_START  = 0;
const LINE_START    = 22;
const NODE_START    = 35;
const NODE_STAGGER  = 18;

// ── Timeline node ─────────────────────────────────────────────────────────────
const TimelineNode: React.FC<{
  event: TimelineEvent;
  index: number;
  frame: number;
  fps: number;
  isLast: boolean;
}> = ({ event, index, frame, fps, isLast }) => {
  const delay   = NODE_START + index * NODE_STAGGER;
  const prog    = spring({ frame: frame - delay, fps, config: SPRINGS.row });
  const opacity = interpolate(prog, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const transY  = interpolate(prog, [0, 1], [28, 0], { extrapolateRight: "clamp" });
  const scale   = interpolate(prog, [0, 1], [0.85, 1], { extrapolateRight: "clamp" });

  const [r, g, b] = hexToRgb(event.clubColor);

  return (
    <div
      style={{
        opacity,
        transform: `translateY(${transY}px) scale(${scale})`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        flex: 1,
        minWidth: 0,
        position: "relative",
      }}
    >
      {/* Year label */}
      <div
        style={{
          fontSize: 13,
          fontWeight: 700,
          letterSpacing: 1.5,
          color: event.isHighlight ? COLORS.gold : COLORS.muted,
          textTransform: "uppercase",
          fontFamily,
          marginBottom: 14,
        }}
      >
        {event.year}
      </div>

      {/* Badge circle */}
      <div
        style={{
          width: 88,
          height: 88,
          borderRadius: "50%",
          backgroundColor: rgbaFromHex(event.clubColor, event.isHighlight ? 0.15 : 0.08),
          border: `2px solid ${rgbaFromHex(event.clubColor, event.isHighlight ? 0.4 : 0.2)}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: event.isHighlight
            ? `0 8px 28px rgba(${r},${g},${b},0.35), 0 0 0 4px ${COLORS.champion.pill}`
            : `0 4px 14px rgba(${r},${g},${b},0.15)`,
          position: "relative",
          zIndex: 2,
        }}
      >
        <img
          src={staticFile(`badges/${event.badgeSlug}`)}
          width={58}
          height={58}
          style={{ objectFit: "contain" }}
        />
      </div>

      {/* Club name */}
      <div
        style={{
          fontSize: 15,
          fontWeight: event.isHighlight ? 700 : 600,
          color: COLORS.primary,
          fontFamily,
          textAlign: "center",
          marginTop: 14,
          letterSpacing: -0.2,
        }}
      >
        {event.club}
      </div>

      {/* Detail */}
      {event.detail && (
        <div
          style={{
            fontSize: 12,
            fontWeight: 400,
            color: COLORS.muted,
            fontFamily,
            textAlign: "center",
            marginTop: 5,
            maxWidth: 140,
            lineHeight: 1.4,
          }}
        >
          {event.detail}
        </div>
      )}
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const CareerTimeline: React.FC<CareerTimelineProps> = ({ playerName, events }) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: SPRINGS.header });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  // The connecting line draws in progressively
  const lineProg = spring({ frame: frame - LINE_START, fps, config: SPRINGS.cols });
  const lineW    = interpolate(lineProg, [0, 1], [0, 100], { extrapolateRight: "clamp" });

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: 100,
          paddingRight: 100,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        {/* Header */}
        <div
          style={{
            opacity: hOpacity,
            transform: `translateY(${hY}px)`,
            marginBottom: 56,
          }}
        >
          <Overline>Career Timeline</Overline>
          <DisplayTitle>{playerName}</DisplayTitle>
        </div>

        {/* Timeline row */}
        <div style={{ position: "relative" }}>
          {/* Connecting line (behind nodes) */}
          <div
            style={{
              position: "absolute",
              top: 86 + 14 + 44, // year label height + margin + half badge
              left: "8%",
              width: `${lineW}%`,
              height: 2,
              backgroundColor: COLORS.divider,
              borderRadius: 1,
              transform: "translateY(-50%)",
              zIndex: 1,
            }}
          />

          {/* Nodes */}
          <div style={{ display: "flex", alignItems: "flex-start", gap: 0 }}>
            {events.map((event, i) => (
              <TimelineNode
                key={i}
                event={event}
                index={i}
                frame={frame}
                fps={fps}
                isLast={i === events.length - 1}
              />
            ))}
          </div>
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
