/**
 * QuoteCard — Cinematic full-screen quote display.
 * Large quote text with a background monogram mark, attribution, and optional context line.
 * Used for player quotes, manager reactions, journalist verdicts.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  hexToRgb,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const QuoteCardPropsSchema = z.object({
  quote:        z.string(),                        // The quote text (without quotation marks)
  attribution:  z.string(),                        // e.g. "Luis Suárez"
  context:      z.string().optional(),             // e.g. "After the ban, July 2014"
  accentColor:  z.string().default("#C8102E"),     // Club / episode accent colour
});

export type QuoteCardProps = z.infer<typeof QuoteCardPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const GLOW_START    = 0;
const MARK_START    = 5;
const QUOTE_START   = 18;
const ATTR_START    = 55;
const CTX_START     = 70;

// ── Main composition ───────────────────────────────────────────────────────────
export const QuoteCard: React.FC<QuoteCardProps> = ({
  quote,
  attribution,
  context,
  accentColor = "#C8102E",
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.015]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -6]);

  const mk = (start: number, cfg = SPRINGS.feature) =>
    spring({ frame: frame - start, fps, config: cfg });

  const glowProg  = mk(GLOW_START,  SPRINGS.header);
  const markProg  = mk(MARK_START,  SPRINGS.cols);
  const quoteProg = mk(QUOTE_START, SPRINGS.header);
  const attrProg  = mk(ATTR_START,  SPRINGS.row);
  const ctxProg   = mk(CTX_START,   SPRINGS.cols);

  const op = (p: typeof glowProg, max = 1) =>
    interpolate(p, [0, 0.5], [0, max], { extrapolateRight: "clamp" });
  const ty = (p: typeof glowProg, dist = 30) =>
    interpolate(p, [0, 1], [dist, 0], { extrapolateRight: "clamp" });

  const [r, g, b] = hexToRgb(accentColor);

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />

      {/* Accent glow behind quote area */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse at center, rgba(${r},${g},${b},0.10) 0%, transparent 60%)`,
          opacity: op(glowProg),
          pointerEvents: "none",
        }}
      />

      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingLeft: 160,
          paddingRight: 160,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        {/* Background quotation mark */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -54%)",
            fontSize: 520,
            fontWeight: 900,
            color: accentColor,
            opacity: interpolate(op(markProg), [0, 1], [0, 0.06], { extrapolateRight: "clamp" }),
            fontFamily,
            lineHeight: 1,
            userSelect: "none",
            pointerEvents: "none",
            letterSpacing: -20,
          }}
        >
          "
        </div>

        {/* Accent bar */}
        <div
          style={{
            width: interpolate(op(quoteProg), [0, 1], [0, 80], { extrapolateRight: "clamp" }),
            height: 4,
            backgroundColor: accentColor,
            borderRadius: 2,
            marginBottom: 36,
            opacity: op(quoteProg),
            boxShadow: `0 0 12px 3px rgba(${r},${g},${b},0.4)`,
          }}
        />

        {/* Quote text */}
        <div
          style={{
            opacity: op(quoteProg),
            transform: `translateY(${ty(quoteProg, 24)}px)`,
            maxWidth: 1360,
            textAlign: "center",
            marginBottom: 52,
          }}
        >
          <span
            style={{
              fontSize: quote.length > 200 ? 36 : quote.length > 120 ? 44 : 54,
              fontWeight: 700,
              color: COLORS.primary,
              fontFamily,
              lineHeight: 1.35,
              letterSpacing: -0.5,
            }}
          >
            "{quote}"
          </span>
        </div>

        {/* Attribution */}
        <div
          style={{
            opacity: op(attrProg),
            transform: `translateY(${ty(attrProg, 16)}px)`,
            display: "flex",
            alignItems: "center",
            gap: 16,
          }}
        >
          <div
            style={{
              width: 32,
              height: 2,
              backgroundColor: accentColor,
              borderRadius: 1,
            }}
          />
          <span
            style={{
              fontSize: 22,
              fontWeight: 700,
              color: accentColor,
              fontFamily,
              letterSpacing: 1,
              textTransform: "uppercase",
            }}
          >
            {attribution}
          </span>
        </div>

        {/* Context */}
        {context && (
          <div
            style={{
              opacity: op(ctxProg),
              transform: `translateY(${ty(ctxProg, 12)}px)`,
              marginTop: 12,
              textAlign: "center",
            }}
          >
            <span
              style={{
                fontSize: 17,
                fontWeight: 400,
                color: COLORS.muted,
                fontFamily,
                letterSpacing: 0.3,
              }}
            >
              {context}
            </span>
          </div>
        )}
      </AbsoluteFill>

    </DocumentaryFrame>
  );
};
