/**
 * PlayerStats — Feature card for a single player's season statistics.
 * Left panel: identity (name, club, season). Right panel: stats grid.
 */
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { z } from "zod";
import {
  fontFamily,
  COLORS,
  SPRINGS,
  Grain,
  Vignette,
  Background,
  Card,
  AccentBar,
  Overline,
  DisplayTitle,
  MetaLine,
  hexToRgb,
  rgbaFromHex,
  DocumentaryFrame,
} from "./shared";

// ── Schema ─────────────────────────────────────────────────────────────────────

export const StatItemSchema = z.object({
  label: z.string(),
  value: z.union([z.string(), z.number()]),
  sub:   z.string().optional(), // e.g. "per 90" or "in 38 games"
});

export const PlayerStatsPropsSchema = z.object({
  playerName: z.string(),
  club:       z.string(),
  season:     z.string(),
  competition: z.string().default("Premier League"),
  badgeSlug:  z.string(),
  clubColor:  z.string(),
  stats:      z.array(StatItemSchema), // up to 6 stat tiles
});

export type StatItem        = z.infer<typeof StatItemSchema>;
export type PlayerStatsProps = z.infer<typeof PlayerStatsPropsSchema>;

// ── Timing ─────────────────────────────────────────────────────────────────────
const HEADER_START  = 0;
const BADGE_START   = 15;
const STAT_START    = 35;
const STAT_STAGGER  = 12;

// ── Stat Tile ──────────────────────────────────────────────────────────────────
const StatTile: React.FC<{
  stat: StatItem;
  index: number;
  frame: number;
  fps: number;
  color: string;
}> = ({ stat, index, frame, fps, color }) => {
  const delay   = STAT_START + index * STAT_STAGGER;
  const prog    = spring({ frame: frame - delay, fps, config: SPRINGS.row });
  const opacity = interpolate(prog, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const scale   = interpolate(prog, [0, 1], [0.88, 1], { extrapolateRight: "clamp" });
  const [r, g, b] = hexToRgb(color);

  // Animated width for the bottom accent line
  const accentWidth = interpolate(prog, [0.3, 1], [0, 100], { extrapolateRight: "clamp" });

  return (
    <div
      style={{
        opacity,
        transform: `scale(${scale})`,
        // Glassmorphism
        backgroundColor: "rgba(255, 255, 255, 0.7)",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        border: "1px solid rgba(255, 255, 255, 0.5)",
        borderRadius: 20,
        padding: "30px 35px 28px",
        boxShadow: "0 8px 32px rgba(0,0,0,0.08)",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Bottom accent line — animated */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: `${accentWidth}%`,
          height: 4,
          backgroundColor: color,
          boxShadow: `0 -2px 10px rgba(${r}, ${g}, ${b}, 0.3)`,
        }}
      />
      <div
        style={{
          fontSize: 14,
          fontWeight: 700,
          letterSpacing: 1.8,
          color: COLORS.muted,
          textTransform: "uppercase",
          fontFamily,
          marginBottom: 10,
        }}
      >
        {stat.label}
      </div>
      <div
        style={{
          fontSize: 72,
          fontWeight: 900,
          color: COLORS.primary,
          fontFamily,
          lineHeight: 1,
          letterSpacing: -3,
        }}
      >
        {stat.value}
      </div>
      {stat.sub && (
        <div
          style={{
            fontSize: 14,
            fontWeight: 400,
            color: COLORS.muted,
            fontFamily,
            marginTop: 8,
          }}
        >
          {stat.sub}
        </div>
      )}
    </div>
  );
};

// ── Main composition ───────────────────────────────────────────────────────────
export const PlayerStats: React.FC<PlayerStatsProps> = ({
  playerName,
  club,
  season,
  competition,
  badgeSlug,
  clubColor,
  stats,
}) => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();

  const bgScale  = interpolate(frame, [0, durationInFrames], [1, 1.02]);
  const cntScale = interpolate(frame, [0, durationInFrames], [1, 1.03]);
  const cntDrift = interpolate(frame, [0, durationInFrames], [0, -10]);

  const hProg    = spring({ frame: frame - HEADER_START, fps, config: SPRINGS.header });
  const hOpacity = interpolate(hProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const hY       = interpolate(hProg, [0, 1], [-20, 0], { extrapolateRight: "clamp" });

  const bProg    = spring({ frame: frame - BADGE_START, fps, config: SPRINGS.feature });
  const bOpacity = interpolate(bProg, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const bScale   = interpolate(bProg, [0, 1], [0.8, 1], { extrapolateRight: "clamp" });

  const [r, g, b] = hexToRgb(clubColor);
  
  // Use first 4 stats and force 2x2 grid
  const displayStats = stats.slice(0, 4);
  const gridCols = 2;

  return (
    <DocumentaryFrame>
      <Background scale={bgScale} />
      <Grain />
      <Vignette />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: 100,
          paddingRight: 100,
          transform: `scale(${cntScale}) translateY(${cntDrift}px)`,
          transformOrigin: "center center",
        }}
      >
        <div style={{ width: 1400 }}>
          {/* ── Top section: Identity ── */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              marginBottom: 60,
              opacity: hOpacity,
              transform: `translateY(${hY}px)`,
            }}
          >
            {/* Club badge */}
            <div
              style={{
                opacity: bOpacity,
                transform: `scale(${bScale})`,
                transformOrigin: "center center",
                marginRight: 40,
              }}
            >
              <div
                style={{
                  width: 140,
                  height: 140,
                  borderRadius: 20,
                  backgroundColor: "#fff",
                  border: `1px solid rgba(0,0,0,0.08)`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  boxShadow: `0 12px 40px rgba(0,0,0,0.08)`,
                }}
              >
                <img
                  src={staticFile(`badges/${badgeSlug}`)}
                  width={100}
                  height={100}
                  style={{ objectFit: "contain" }}
                />
              </div>
            </div>

            <div>
              <Overline>{competition}</Overline>
              <DisplayTitle size={90}>{playerName}</DisplayTitle>
              <div style={{ marginTop: 8 }}>
                <MetaLine color={COLORS.primary}>
                  <span style={{ fontSize: 24, fontWeight: 600 }}>{club}</span> · {season} Season
                </MetaLine>
              </div>
            </div>
          </div>

          {/* ── Bottom section: Stats grid ── */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: `repeat(${gridCols}, 1fr)`,
              gap: 30,
              marginBottom: 40,
            }}
          >
            {displayStats.map((stat, i) => (
              <StatTile
                key={stat.label}
                stat={stat}
                index={i}
                frame={frame}
                fps={fps}
                color={clubColor}
              />
            ))}
          </div>

          {/* Full-width bottom accent line */}
          <div
            style={{
              width: "100%",
              height: 8,
              borderRadius: 4,
              backgroundColor: clubColor,
              boxShadow: `0 0 20px 5px rgba(${r},${g},${b},0.3)`,
              opacity: hOpacity,
              transform: `scaleX(${hProg})`,
              transformOrigin: "left center",
            }}
          />
        </div>

      </AbsoluteFill>
    </DocumentaryFrame>
  );
};
